//! Generator for `src/hash/poseidon_bn254_tables.rs` (`@generated` constants).
//!
//! Emits, using only the public API, the circomlib / poseidon-lite BN254
//! tables for widths `t = 2..=17` as Montgomery LE limbs:
//! - `C{t}`: `(R_F + R_P) * t` Grain-LFSR round constants (rejection-sampled),
//! - `M{t}`: `t*t` Cauchy-MDS entries, row-major (first-candidate matrix with
//!   Grain-stream-drawn `x`/`y`, matching poseidon-lite bit-for-bit).
//!
//! The Grain construction is the hadeshash reference
//! (`generate_parameters_grain.sage 1 0 254 <t> 8 <R_P> <BN254-Fr>`):
//! 80-bit LFSR (taps 62/51/38/23/13/0), 160 warm-up clocks, self-shrinking
//! output, MSB-first `n`-bit sampling. `R_P` is the per-width rounded value
//! (`[56, 57, 56, 60, 60, 63, 64, 63, 60, 66, 60, 65, 70, 60, 64, 68]`).
//!
//! Run: `cargo run --example gen_poseidon_bn254_tables`
//! and redirect stdout to `src/hash/poseidon_bn254_tables.rs`. Then run the
//! `poseidon_bn254` KAT suites (Dart-derived vectors) before committing.

use blockchain_utils::curve::bn254::Scalar;
use std::collections::HashSet;

const RP: [usize; 16] = [
    56, 57, 56, 60, 60, 63, 64, 63, 60, 66, 60, 65, 70, 60, 64, 68,
];
const R_F: usize = 8;
const N_BITS: usize = 254;

// BN254 scalar field (Fr) modulus, BE (for mod-p reduction of MDS draws).
const P_BE: [u8; 32] = [
    0x30, 0x64, 0x4e, 0x72, 0xe1, 0x31, 0xa0, 0x29, 0xb8, 0x50, 0x45, 0xb6,
    0x81, 0x81, 0x58, 0x5d, 0x28, 0x33, 0xe8, 0x48, 0x79, 0xb9, 0x70, 0x91,
    0x43, 0xe1, 0xf5, 0x93, 0xf0, 0x00, 0x00, 0x01,
];

fn be_ge(a: &[u8; 32], b: &[u8; 32]) -> bool {
    for i in 0..32 {
        if a[i] != b[i] {
            return a[i] > b[i];
        }
    }
    true
}

fn be_sub_p(a: &[u8; 32]) -> [u8; 32] {
    let mut out = [0u8; 32];
    let mut borrow: i32 = 0;
    for i in (0..32).rev() {
        let v = a[i] as i32 - P_BE[i] as i32 - borrow;
        if v < 0 {
            out[i] = (v + 256) as u8;
            borrow = 1;
        } else {
            out[i] = v as u8;
            borrow = 0;
        }
    }
    out
}

// ---- Grain LFSR (hadeshash reference semantics) ----
fn clock(s: u128) -> (u128, u8) {
    let bit = |i: u32| ((s >> (79 - i)) & 1) as u8;
    let new = bit(62) ^ bit(51) ^ bit(38) ^ bit(23) ^ bit(13) ^ bit(0);
    ((((s << 1) & ((1u128 << 80) - 1)) | new as u128), new)
}

fn push_bits(bits: &mut Vec<u8>, v: usize, w: u32) {
    for i in (0..w).rev() {
        bits.push(((v >> i) & 1) as u8);
    }
}

struct Grain {
    s: u128,
}

impl Grain {
    fn new(t: usize, rf: usize, rp: usize) -> Self {
        let mut bits: Vec<u8> = Vec::with_capacity(80);
        push_bits(&mut bits, 1, 2); // prime field
        push_bits(&mut bits, 0, 4); // x^alpha s-box
        push_bits(&mut bits, 254, 12);
        push_bits(&mut bits, t, 12);
        push_bits(&mut bits, rf, 10);
        push_bits(&mut bits, rp, 10);
        bits.extend(std::iter::repeat_n(1, 30));
        let mut s: u128 = 0;
        for b in bits {
            s = (s << 1) | b as u128;
        }
        for _ in 0..160 {
            s = clock(s).0;
        }
        Grain { s }
    }
    fn gen_bit(&mut self) -> u8 {
        let (s, mut new) = clock(self.s);
        self.s = s;
        while new == 0 {
            self.s = clock(self.s).0;
            let (s2, n2) = clock(self.s);
            self.s = s2;
            new = n2;
        }
        let (s3, out) = clock(self.s);
        self.s = s3;
        out
    }
    /// MSB-first `n`-bit integer as 32 BE bytes.
    fn bits_be(&mut self, n: usize) -> [u8; 32] {
        let mut be = [0u8; 32];
        for i in 0..n {
            let b = self.gen_bit();
            let k = n - 1 - i; // value-bit index (0 = LSB)
            be[31 - k / 8] |= b << (k % 8);
        }
        be
    }
}

fn fmt_limbs(limbs: &[u64; 4]) -> String {
    format!(
        "    [{:#018x}, {:#018x}, {:#018x}, {:#018x}],\n",
        limbs[0], limbs[1], limbs[2], limbs[3]
    )
}

fn main() {
    let mut out = String::new();
    out.push_str(
        "//! GENERATED by `cargo run --example gen_poseidon_bn254_tables`\n\
         //! (circomlib / poseidon-lite BN254 tables: Grain-LFSR round constants +\n\
         //! first-candidate Cauchy MDS, Montgomery LE limbs).\n\
         //! Do not edit by hand.\n\n",
    );
    let mut c_names = Vec::new();
    let mut m_names = Vec::new();
    for (idx, t) in (2usize..=17).enumerate() {
        let rp = RP[idx];
        let mut g = Grain::new(t, R_F, rp);
        // Round constants (rejection-sampled).
        let need = (R_F + rp) * t;
        let mut rc: Vec<[u64; 4]> = Vec::with_capacity(need);
        while rc.len() < need {
            let be = g.bits_be(N_BITS);
            if let Ok(f) = Scalar::from_bytes_be(&be) {
                rc.push(f.to_mont_limbs());
            }
        }
        // MDS first candidate: stream-drawn x/y (mod-p semantics), Cauchy.
        let (xs, ys) = loop {
            let mut draws: Vec<[u8; 32]> = Vec::with_capacity(2 * t);
            while draws.len() < 2 * t {
                let mut be = g.bits_be(N_BITS);
                if be_ge(&be, &P_BE) {
                    be = be_sub_p(&be);
                }
                draws.push(be);
            }
            if draws.iter().collect::<HashSet<_>>().len() == draws.len() {
                let xs: Vec<Scalar> = draws[..t]
                    .iter()
                    .map(|b| Scalar::from_bytes_be(b).unwrap())
                    .collect();
                let ys: Vec<Scalar> = draws[t..]
                    .iter()
                    .map(|b| Scalar::from_bytes_be(b).unwrap())
                    .collect();
                let mut bad = false;
                for x in xs.iter().take(t) {
                    for y in ys.iter().take(t) {
                        if x.add(y).is_zero() {
                            bad = true;
                        }
                    }
                }
                if !bad {
                    break (xs, ys);
                }
            }
        };
        // Cauchy entries via one batch inversion (Montgomery trick).
        let n = t * t;
        let mut denoms = Vec::with_capacity(n);
        for x in xs.iter().take(t) {
            for y in ys.iter().take(t) {
                denoms.push(x.add(y));
            }
        }
        let mut pref = vec![Scalar::one(); n];
        for i in 1..n {
            pref[i] = pref[i - 1].mul(&denoms[i - 1]);
        }
        let mut inv_all = pref[n - 1].mul(&denoms[n - 1]).invert().unwrap();
        let mut m: Vec<[u64; 4]> = vec![[0u64; 4]; n];
        for i in (0..n).rev() {
            m[i] = inv_all.mul(&pref[i]).to_mont_limbs();
            inv_all = inv_all.mul(&denoms[i]);
        }
        let cn = format!("C{}", t);
        let mn = format!("M{}", t);
        out.push_str(&format!("pub(crate) const {}: [[u64; 4]; {}] = [\n", cn, need));
        for l in &rc {
            out.push_str(&fmt_limbs(l));
        }
        out.push_str("];\n");
        out.push_str(&format!("pub(crate) const {}: [[u64; 4]; {}] = [\n", mn, n));
        for l in &m {
            out.push_str(&fmt_limbs(l));
        }
        out.push_str("];\n");
        c_names.push((t, cn, need));
        m_names.push((t, mn, n));
    }
    out.push_str(
        "\n/// Round constants for width `t` (`2..=17`), `(R_F + R_P) * t`\n\
         /// Montgomery LE limbs. Empty slice for unsupported widths.\n\
         pub(crate) fn round_constants(t: usize) -> &'static [[u64; 4]] {\n    match t {\n",
    );
    for (t, name, _) in &c_names {
        out.push_str(&format!("        {} => &{},\n", t, name));
    }
    out.push_str("        _ => &[],\n    }\n}\n");
    out.push_str(
        "\n/// MDS matrix for width `t` (`2..=17`), row-major `t * t`\n\
         /// Montgomery LE limbs. Empty slice for unsupported widths.\n\
         pub(crate) fn mds_matrix(t: usize) -> &'static [[u64; 4]] {\n    match t {\n",
    );
    for (t, name, _) in &m_names {
        out.push_str(&format!("        {} => &{},\n", t, name));
    }
    out.push_str("        _ => &[],\n    }\n}\n");
    print!("{}", out);
}
